static vis_budget qb(void){vis_budget b={{20000000,800000000,300000000},{0,0,0}};return b;}
static FoxDiskScene lamps(int side,double power){FoxDiskScene s;FoxDiskLightInput a[3]={0};for(int i=0;i<3;i++){a[i].shape=FOX_DISK_SHAPE_DISK;a[i].center[2]=-5*side;a[i].diameter=.5;a[i].power=power;a[i].rotation_xyz[0]=side>0?3.14159265358979323846:0;for(int k=0;k<3;k++)a[i].color[k]=1;}double world[3]={10,20,30};assert(fox_disk_scene_init(&s,a,world,1)==FOX_DISK_OK);return s;}
static bounce_generation gen(void){bounce_generation g={.visibility={1,1,1},.material=1,.emission=1};return g;}
static bounce_ground gr(int mode){bounce_ground g={.mode=mode,.object_id=77,.first_triangle=0,.triangle_count=2,.le={.18,2,4}};if(mode==3){g.rho[0]=.84;g.rho[1]=.78;g.rho[2]=.65;}return g;}
static vis_scene *geometry(int side,int blocker,int reverse){double xyz[24];for(int j=0;j<2;j++){double z=(j?-.5:1)*side;double q[12]={-100,-100,z,100,-100,z,100,100,z,-100,100,z};memcpy(xyz+12*j,q,sizeof q);}uint32_t ix[]={0,1,2,0,2,3,4,5,6,4,6,7};if(reverse)for(int j=0;j<4;j++){uint32_t t=ix[3*j];ix[3*j]=ix[3*j+1];ix[3*j+1]=t;}vis_scene *s=NULL;assert(vis_scene_build(&s,xyz,blocker?8:4,ix,blocker?4:2,gen().visibility,(vis_limits){2048,4095,524288})==VIS_OK);return s;}
static bounce_scene *scene(vis_scene *v,FoxDiskScene *l,bounce_generation g,bounce_ground *ground){bounce_triangle a[4]={0};for(int t=0;t<4;t++){a[t].double_sided=1;for(int j=0;j<3;j++){a[t].v[j].front[2]=32767;a[t].v[j].back[2]=-32767;}}bounce_scene *s=NULL;assert(bounce_scene_build_ground(&s,v,a,vis_scene_triangle_count(v),l,-1,g,262144,ground)==BOUNCE_OK);memset(a,0xa5,sizeof a);return s;}
static bounce_status run(bounce_scene *s,bounce_generation g,int side,bounce_floor_work *w,vis_budget *db,vis_budget *tb,bounce_result *out,int legacy){bounce_binding b={0};assert(bounce_binding_set(&b,s,g)==BOUNCE_OK);double p[3]={0},n[3]={0,0,side},r[3]={.2,.4,.6};bounce_status st=legacy?bounce_eval(&b,g,p,n,r,BOUNCE_ONE,16,16,db,tb,out):bounce_eval_floor_experimental(&b,g,p,n,r,BOUNCE_ONE,16,16,db,tb,w,out);bounce_binding_clear(&b);return st;}
static void eq3(const double a[3],const double b[3]){for(int k=0;k<3;k++)assert(fabs(a[k]-b[k])<1e-11);}
static void fresh(bounce_floor_work *w,vis_budget *a,vis_budget *b){assert(bounce_floor_work_init(w,1,16)==BOUNCE_OK);*a=qb();*b=qb();}
